(2224, 'مانکن پایه دار سوزن خور، اتوخور، فوم سرد', 'admin', 12, 63, 0, NULL, NULL, '[\"uploads\\/products\\/wp\\/2025\\/11\\/IMG_20251129_122726_copy_699x699.jpg\"]', 'uploads/products/wp/2025/11/IMG_20251129_122726_copy_699x699.jpg', 'uploads/products/wp/2025/11/IMG_20251129_122726_copy_699x699.jpg', NULL, NULL, NULL, '', '<ul>\r\n 	<li><strong>روش ارسال  مانکن فقط تیپاکس</strong>این مانکن با فوم سرد درجه‌یک ساخته شده که باعث می‌شه در استفاده طولانی‌مدت فرم خودش رو از دست نده و ظاهرش همیشه شیک و سالم بمونه.✔️ دیـه‌سایک نِتو‌خورَد (روکش نِت‌دار و قابل‌تنفس)\r\n✔️ سوزن‌خورَد کامل – برای نصب گل‌سینه، سنجاق‌سینه، پارچه، خرجکار و نمونه‌دوزی عالیه\r\n✔️ فومِ سرد – نشکن، سبک، ماندگار\r\n✔️ برشِ دقیق و تمیز – فرم صاف و ایستایی عالی برای نمایش حرفه‌ای محصولاتاین مانکن برای نمایش:گل‌سینهتور\r\n\r\nپارچه\r\n\r\nخرجکار\r\n\r\nشال‌گردن\r\n\r\nروبان و یراق\r\n\r\nزیورآلات پارچه‌ای\r\nعالی و کاربردیه.\r\n\r\n? مناسب فروشندگان، تولیدی‌ها و پیج‌های خرازی مثل پرنسا</li>\r\n</ul>', 4500000, 0, 1, '[4,10]', '[{\"attribute_id\":4,\"values\":[\"کرمی\",\"مشکی\"]},{\"attribute_id\":10,\"values\":[\"سایز36\",\"سایز38\",\"سایز40\",\"سایز42\",\"سایز44\"]}]', '[]', NULL, 0, 1, 0, 16, 'عدد', 0.00, 'percent', 0.00, 'amount', 'flat_rate', 0.00, 2, 'مانکن پایه دار سوزن خور، اتوخور، فوم سرد', 'مانکن فوم سرد – سوزن‌خور و اتو خور\r\nبرای عکسای حرفه‌ای محصولات خرازی ❤️\r\n✓ فوم سرد\r\n✓ برش تمیز\r\n✓ سوزن‌خود کامل\r\n✓ سبک و مقاوم', 'uploads/products/wp/2025/11/IMG_20251129_122726_copy_699x699.jpg', NULL, 'mankn-paih-dar-sozn-khor-atokhor-fom-sr-wp-9923', 0.00, NULL, 0, NULL, NULL, '2025-11-29 20:05:09', '2026-10-03 21:14:03'),
(2225, 'مروارید سنگی سایز6 طوسی', 'admin', 12, 67, 1148, NULL, NULL, '[\"uploads\\/products\\/wp\\/2025\\/11\\/Morvarid-Sangi-Size6_13.jpg\"]', 'uploads/products/wp/2025/11/Morvarid-Sangi-Size6_13.jpg', 'uploads/products/wp/2025/11/Morvarid-Sangi-Size6_13.jpg', NULL, NULL, NULL, 'مروارید سنگی,مروارید سایز 6,مهره مرواریدی,مهره سنگی,سنگ کار دست‌ساز,لوازم خرازی,مهره زیورآلات,اکسسوری‌سازی,ساخت دستبند,ساخت گردنبند', '<ul>\r\n 	<li><strong>مروارید سنگی سایز 6 یک مهره زیبا و باکیفیت است که ظاهری براق دارد و در ساخت انواع زیورآلات و اکسسوری‌های دست‌ساز استفاده می‌شود.</strong></li>\r\n 	<li><strong>سطح براق و صیقلی این مهره‌ها جلوه‌ای شیک و حرفه‌ای به کارهای دست‌ساز شما می‌دهد و به‌خاطر وزن مناسب و رنگ ثابت، انتخابی عالی برای دستبند، گردنبند، پابند و استفاده در کارهای خرازی است.</strong></li>\r\n 	<li><strong>این مرواریدها دوام بالا داشته و به‌راحتی با انواع سنگ‌ها و مهره‌های دیگر ست می‌شوند.</strong></li>\r\n 	<li><strong>برای هنرمندانی که به کیفیت و زیبایی اهمیت می‌دهند، مروارید سنگی سایز 6 یک گزینه ایده‌آل است.</strong></li>\r\n 	<li><strong> </strong></li>\r\n</ul>', 152404, 0, 0, '[]', '[]', '[]', NULL, 0, 1, 0, 5, 'عدد', 0.00, 'percent', 0.00, 'amount', 'flat_rate', 0.00, 1, 'مروارید سنگی سایز6 طوسی', '<ul>\r\n 	<li><strong>مروارید سنگی براق و باکیفیت سایز 6 مناسب ساخت انواع زیورآلات. رنگ ثابت، سطح صیقلی و ایده‌آل برای کارهای خرازی و دست‌ساز.\r\n</strong></li>\r\n</ul>', 'uploads/products/wp/2025/11/Morvarid-Sangi-Size6_13.jpg', NULL, 'mroarid-sngi-saiz6-tosi-wp-9943', 0.00, NULL, 0, NULL, NULL, '2025-11-30 16:25:38', '2026-10-05 15:41:33'),
