(2840, 'مروارید اقتصادی و با کیفیت نیم کیلویی', 'admin', 12, 67, 1150, NULL, NULL, '[\"uploads\\/products\\/wp\\/2026\\/02\\/1771506219116_copy_918x918.jpg\"]', 'uploads/products/wp/2026/02/1771506219116_copy_918x918.jpg', 'uploads/products/wp/2026/02/1771506219116_copy_918x918.jpg', NULL, NULL, NULL, 'مروارید نیم کیلویی,مروارید سفید,مروارید مشکی,مروارید شیری,مروارید تزئینی,جواهر دوزی,تاج سازی,خرجکار لباس,لوازم خرازی', '<ul>\r\n 	<li><strong>مرواریدهای نیم کیلویی در رنگ‌های سفید، مشکی و شیری، انتخابی اقتصادی و کاربردی برای جواهر‌دوزی، تزیین لباس و ساخت اکسسوری هستند. این مرواریدها با سطح صاف و درخشش زیبا، جلوه‌ای کلاسیک و شیک به کار می‌دهند و برای دوخت روی لباس‌های مجلسی، مانتو، تاج‌سازی، گل‌سرسازی و انواع کارهای هنری بسیار مناسب‌اند.</strong></li>\r\n 	<li><strong>بسته‌بندی نیم کیلویی گزینه‌ای مقرون‌به‌صرفه برای مزون‌ها و تولیدی‌ها محسوب می‌شود و برای کارهای عمده و حرفه‌ای کاملاً کاربردی است.</strong></li>\r\n</ul>', 772133, 0, 1, '[4,10]', '[{\"attribute_id\":4,\"values\":[\"مشکی\",\"شیری\",\"سفید\"]},{\"attribute_id\":10,\"values\":[\"سایز8\",\"سایز6\"]}]', '[]', NULL, 0, 1, 0, 3, 'عدد', 0.00, 'percent', 0.00, 'amount', 'flat_rate', 0.00, 7, 'مروارید اقتصادی و با کیفیت نیم کیلویی', '<ul>\r\n 	<li><strong>مروارید نیم کیلویی در رنگ‌های سفید، مشکی و شیری، اقتصادی و مناسب جواهر‌دوزی و تزیین لباس.</strong></li>\r\n</ul>', 'uploads/products/wp/2026/02/1771506219116_copy_918x918.jpg', NULL, 'mroarid-nim-kiloii-wp-12284', 0.00, NULL, 0, NULL, NULL, '2026-02-20 20:34:49', '2026-10-05 15:41:26'),
(2841, 'تور دوطرفه گل دار پهن', 'admin', 12, 84, 0, NULL, NULL, '[\"uploads\\/products\\/wp\\/2026\\/02\\/IMG_20260221_142306_copy_609x627.jpg\"]', 'uploads/products/wp/2026/02/IMG_20260221_142306_copy_609x627.jpg', 'uploads/products/wp/2026/02/IMG_20260221_142306_copy_609x627.jpg', NULL, NULL, NULL, 'تور دوطرفه گل‌دار ظریف و شیک، مناسب تزیین لباس‌های مجلسی، تل و اکسسوری مو.', '<ul>\r\n 	<li><strong>تور دوطرفه گل‌دار با طراحی ظریف و نقش‌های گل برجسته در هر دو لبه، انتخابی زیبا و کاربردی برای خیاطی و تزیینات لباس است. این تور به دلیل کار شدن از دو طرف، بدون نیاز به برش اضافه جلوه‌ای کامل و منظم ایجاد می‌کند و برای یقه، آستین، لبه دامن و خرجکار لباس‌های مجلسی بسیار مناسب است.</strong></li>\r\n 	<li><strong>همچنین در تل‌سازی، گل‌سرسازی و تزیینات مو کاربرد فراوان دارد و به‌راحتی روی پارچه دوخته می‌شود. انتخابی عالی برای کارهای مزونی و طراحی‌های ظریف و شیک.</strong></li>\r\n</ul>', 253000, 0, 0, '[]', '[]', '[]', NULL, 0, 1, 0, 1, 'عدد', 0.00, 'percent', 0.00, 'amount', 'flat_rate', 0.00, 3, 'تور دوطرفه گل دار پهن', '<ul>\r\n 	<li><strong>تور دوطرفه گل‌دار ظریف و شیک، مناسب تزیین لباس‌های مجلسی، تل و اکسسوری مو.</strong></li>\r\n</ul>', 'uploads/products/wp/2026/02/IMG_20260221_142306_copy_609x627.jpg', NULL, 'tor-dotrfh-gl-dar-wp-12295', 0.00, NULL, 0, NULL, NULL, '2026-02-21 13:22:54', '2026-09-29 07:37:49'),
