(3349, 'دکمه پینترستی گل 4 تکه بابونه', 'admin', 12, 62, 1158, NULL, NULL, '[\"uploads\\/products\\/wp\\/2026\\/09\\/IMG_20260914_143613_copy_900x900.jpg\"]', 'uploads/products/wp/2026/09/IMG_20260914_143613_copy_900x900.jpg', 'uploads/products/wp/2026/09/IMG_20260914_143613_copy_900x900.jpg', NULL, NULL, NULL, 'دکمه گل,دکمه گل 4 تکه,دکمه رنگ ثابت,دکمه ترند,دکمه خاص,دکمه مانتو,دکمه کت,دکمه پالتو,دکمه مزونی,دکمه شومیز,یراق لباس,لوازم خرازی', 'دکمه گل ۴ تکه یکی از مدل‌های خاص و بسیار ترند برای طراحی و تزئین انواع لباس است. فرم گل‌مانند و طراحی چهار‌تکه این دکمه، ظاهر لباس را از مدل‌های معمولی متفاوت می‌کند و به آن جلوه‌ای شیک، مدرن و خاص می‌دهد.\r\nاین دکمه با رنگ ثابت انتخابی عالی برای استفاده در مانتو، کت، پالتو، شومیز و لباس‌های مزونی است و می‌تواند به‌عنوان یک جزئیات کوچک، تغییر چشمگیری در ظاهر نهایی لباس ایجاد کند.', 630000, 0, 1, '[4]', '[{\"attribute_id\":4,\"values\":[\"مشکی\",\"سفید\"]}]', '[]', NULL, 0, 1, 0, 2, 'عدد', 0.00, 'percent', 0.00, 'amount', 'flat_rate', 0.00, 77, 'دکمه پینترستی گل 4 تکه بابونه', '<strong></strong>دکمه گل ۴ تکه رنگ ثابت و بسیار ترند، مناسب مانتو، کت، پالتو، شومیز و انواع لباس‌های خاص و مزونی.', 'uploads/products/wp/2026/09/IMG_20260914_143613_copy_900x900.jpg', NULL, 'dkmh-pintrsti-gl-4-tkh-wp-15618', 0.00, NULL, 0, NULL, NULL, '2026-09-14 20:39:25', '2026-10-11 21:05:07'),
(3350, 'سنگ متری اتویی', 'admin', 12, 65, 0, NULL, NULL, '[\"uploads\\/products\\/wp\\/2026\\/09\\/IMG_20260914_162113_copy_814x814.jpg\"]', 'uploads/products/wp/2026/09/IMG_20260914_162113_copy_814x814.jpg', 'uploads/products/wp/2026/09/IMG_20260914_162113_copy_814x814.jpg', NULL, NULL, NULL, 'سنگ متری,سنگ متری اتویی,سنگ اتویی,سنگ شیشه‌ای,خرجکار اتویی,نوار سنگی,سنگ لباس,سنگ مانتو,سنگ مجلسی,سنگ مزونی,خرجکار لباس,تزئین لباس,نگین اتویی,یراق لباس,لوازم خرازی', '<strong>سنگ‌های متری اتویی، یک خرجکار بسیار شیک و کاربردی برای تزئین و دیزاین انواع لباس هستند که تمامی سنگ‌های به‌کاررفته در آن از جنس شیشه می‌باشند و به همین دلیل جلوه‌ای براق و چشمگیر روی کار ایجاد می‌کنند. این سنگ‌ها به‌صورت متری آماده هستند و با اتو به‌راحتی روی سطح موردنظر نصب می‌شوند.\r\nمناسب برای تزئین مانتو، کت، شومیز، لباس مجلسی، لباس‌های مزونی، کیف و انواع کارهای هنری و اکسسوری. انتخابی عالی برای زمانی که می‌خواهید در مدت کوتاه، لباس را با یک خرجکار شیک و درخشان متفاوت و خاص کنید.', 1180000, 0, 1, '[4]', '[{\"attribute_id\":4,\"values\":[\"نقره ای\",\"مشکی\",\"سرمه ای\",\"سبز\"]}]', '[]', NULL, 0, 1, 0, 40, 'عدد', 0.00, 'percent', 0.00, 'amount', 'flat_rate', 0.00, 0, 'سنگ متری اتویی', 'سنگ متری اتویی با سنگ‌های تماماً شیشه‌ای، آماده نصب با اتو و مناسب تزئین انواع لباس و کارهای مزونی.', 'uploads/products/wp/2026/09/IMG_20260914_162113_copy_814x814.jpg', NULL, 'sng-mtri-atoii-2-wp-15630', 0.00, NULL, 0, NULL, NULL, '2026-09-15 11:36:53', '2026-10-13 13:02:19'),
